/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen1Test {





    @Test
    public void testAddOrUpdateNewItemWithAutoSort() {
        // autoSort = true
        XYSeries series = new XYSeries("Test", true);
        series.addOrUpdate(2.0, 20.0);
        series.addOrUpdate(1.0, 10.0); // Should be inserted at index 0

        assertEquals(2, series.getItemCount());
