import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen1Test {







    @Test
    public void testAddOrUpdateOverwritesExistingWhenDuplicatesNotAllowed() {
        // allowDuplicateXValues = false (default)
        XYSeries series = new XYSeries("Test", true, false);
        series.addOrUpdate(1.0, 10.0);

        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNotNull("Should return the cloned overwritten item", overwritten);
        assertEquals(1.0, overwritten.getX().doubleValue(), 1e-9);
        assertEquals(10.0, overwritten.getY().doubleValue(), 1e-9);

        assertEquals(1, series.getItemCount());
        assertEquals(20.0, series.getY(0).doubleValue(), 1e-9);
    }






}

