/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen1Test {









    @Test
    public void testAddOrUpdateAllowsDuplicateXWhenPermitted() {
        // allowDuplicateXValues = true
        XYSeries series = new XYSeries("Test", true, true);
        series.addOrUpdate(1.0, 10.0);
        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNull("Should return null because duplicates are allowed", overwritten);
        assertEquals(2, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(10.0, series.getY(0).doubleValue(), 1e-9);
        assertEquals(1.0, series.getX(1).doubleValue(), 1e-9);
        assertEquals(20.0, series.getY(1).doubleValue(), 1e-9);
    }




}

