/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen1Test {











    @Test
    public void testAddOrUpdateRespectsMaximumItemCount() {
        XYSeries series = new XYSeries("Test");
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        // This should trigger removal of index 0 (the 1.0 item)
        series.addOrUpdate(3.0, 30.0);

        assertEquals(2, series.getItemCount());
        assertEquals(2.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(3.0, series.getX(1).doubleValue(), 1e-9);
    }


}

package org.jfree.data.xy;

import java.io.*;
