import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen1Test {













    @Test
    public void testAddOrUpdateWithAutoSortInsertionIndex() {
        // Tests the branch: if (this.autoSort) { this.data.add(-index - 1, ...) }
        // If indexOf returns -2 (meaning it should be at index 1), -(-2) - 1 = 1
        XYSeries series = new XYSeries("Test", true);
        series.addOrUpdate(10.0, 100.0);
        series.addOrUpdate(30.0, 300.0);

        // 20.0 should be inserted at index 1
        series.addOrUpdate(20.0, 200.0);

        assertEquals(3, series.getItemCount());
        assertEquals(10.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(20.0, series.getX(1).doubleValue(), 1e-9);
        assertEquals(30.0, series.getX(2).doubleValue(), 1e-9);
    }
}
